#!/bin/bash
printf "%d.%d.%d.%d\n" "$(( ($1 >= 8) * 255 + ($1 > 0 && $1 < 8) * (256 - (1 << (8 - $1))) ))" "$(( ($1 >= 16) * 255 + ($1 > 8 && $1 < 16) * (256 - (1 << (16 - $1))) ))" "$(( ($1 >= 24) * 255 + ($1 > 16 && $1 < 24) * (256 - (1 << (24 - $1))) ))" "$(( ($1 == 32) * 255 + ($1 > 24 && $1 < 32) * (256 - (1 << (32 - $1))) ))"
